//! Derives the subset of the Handy v3 protobuf code that the protocol sends.
//!
//! `hdy_rpc.rs` is generated by prost-build from the vendor's full schema, where `RpcMessage` is
//! a union of every request, response and notification the device knows. Using it directly drags
//! an encoder, decoder and `Debug` impl for all of them into the binary (~140 KB on a 32-bit
//! target), although the protocol only ever builds a handful of requests.
//!
//! This script copies the definitions the protocol needs verbatim and drops the other oneof
//! variants, so field tags and encodings are unchanged. Protobuf decoders skip unknown fields, so
//! decoding a device reply with the trimmed types still works; it just yields no payload.
//!
//! To use another request in the protocol, add its name to `REQUESTS`.
//!
//! Also generates the `protocol_factory!` macro and tells dependents which protocols exist, see
//! `protocol_factory`.

use std::{env, fmt::Write, fs, path::Path};

const SOURCE: &str = "src/device/protocol_impl/thehandy_v3/hdy_rpc.rs";

const PROTOCOLS_DIR: &str = "src/device/protocol_impl";

/// The `request::Params` variants (and their message structs) the protocol constructs.
const REQUESTS: &[&str] = &[
  "RequestBatteryGet",
  "RequestCapabilitiesGet",
  "RequestHdspXpTSet",
  "RequestHvpSet",
  "RequestHvpStop",
];

fn main() {
  println!("cargo:rerun-if-changed=build.rs");
  protocol_factory();
  println!("cargo:rerun-if-changed={SOURCE}");

  let source = fs::read_to_string(SOURCE).expect("generated Handy v3 protobuf code is readable");
  let mut out = String::from("// Trimmed from hdy_rpc.rs by build.rs. Do not edit.\n");

  for request in REQUESTS {
    out.push_str(item(&source, &format!("pub struct {request} "), SOURCE));
  }

  let (params, tags) = keep_variants(item(&source, "pub mod request ", SOURCE), REQUESTS);
  out.push_str(&with_tags(
    item(&source, "pub struct Request ", SOURCE),
    "request::Params",
    &tags,
  ));
  out.push_str(&params);

  let (message, tags) = keep_variants(item(&source, "pub mod rpc_message ", SOURCE), &["Request"]);
  out.push_str(&with_tags(
    item(&source, "pub struct RpcMessage ", SOURCE),
    "rpc_message::Message",
    &tags,
  ));
  out.push_str(&message);

  out.push_str(item(&source, "pub enum MessageType ", SOURCE));

  let out_dir = env::var("OUT_DIR").expect("cargo sets OUT_DIR");
  fs::write(Path::new(&out_dir).join("thehandy_v3_rpc.rs"), out)
    .expect("trimmed Handy v3 protobuf code is writable");
}

/// The top-level item whose declaration line starts with `header`, including the attributes and
/// doc comments directly above it and a trailing newline.
fn item<'a>(source: &'a str, header: &str, file: &str) -> &'a str {
  let declaration = source
    .match_indices(header)
    .map(|(index, _)| index)
    .find(|&index| index == 0 || source.as_bytes()[index - 1] == b'\n')
    .unwrap_or_else(|| panic!("`{header}` not found in {file}"));

  let mut start = declaration;
  while let Some(previous) = source[..start].strip_suffix('\n') {
    let line_start = previous.rfind('\n').map_or(0, |index| index + 1);
    let line = &previous[line_start..];
    if !(line.starts_with("#[") || line.starts_with("///")) {
      break;
    }
    start = line_start;
  }

  let mut depth = 0usize;
  for (offset, byte) in source[declaration..].bytes().enumerate() {
    match byte {
      b'{' => depth += 1,
      b'}' => {
        depth -= 1;
        if depth == 0 {
          let end = declaration + offset + 1;
          let end = end + usize::from(source[end..].starts_with('\n'));
          return &source[start..end];
        }
      }
      _ => {}
    }
  }
  panic!("`{header}` in {file} has no closing brace");
}

/// Returns the oneof module with only the variants named in `keep`, and their tags as they go in
/// the `tags = "..."` attribute of the field holding the oneof.
fn keep_variants(module: &str, keep: &[&str]) -> (String, String) {
  let mut out = String::new();
  let mut tags = Vec::new();
  let mut found = Vec::new();
  // Doc comments and attributes of the variant that has not been seen yet.
  let mut pending = String::new();
  let mut in_enum = false;

  for line in module.lines() {
    let trimmed = line.trim();
    if !in_enum {
      in_enum = trimmed.starts_with("pub enum ");
      writeln!(out, "{line}").unwrap();
    } else if trimmed.starts_with("///") || trimmed.starts_with("#[") {
      writeln!(pending, "{line}").unwrap();
    } else if let Some((name, _)) = trimmed.split_once("(super::") {
      if keep.contains(&name) {
        let tag = pending
          .split_once("tag = \"")
          .and_then(|(_, rest)| rest.split_once('"'))
          .map(|(tag, _)| tag)
          .unwrap_or_else(|| panic!("variant `{name}` in {SOURCE} has no tag"));
        tags.push(tag.to_owned());
        found.push(name);
        out.push_str(&pending);
        writeln!(out, "{line}").unwrap();
      }
      pending.clear();
    } else {
      in_enum = trimmed != "}";
      writeln!(out, "{line}").unwrap();
    }
  }

  for name in keep {
    assert!(
      found.contains(name),
      "variant `{name}` not found in {SOURCE}"
    );
  }
  (out, tags.join(", "))
}

/// Returns the message struct with the tag list of its `oneof` field replaced by `tags`.
fn with_tags(message: &str, oneof: &str, tags: &str) -> String {
  let marker = format!("oneof = \"{oneof}\"");
  let after_oneof = message
    .find(&marker)
    .unwrap_or_else(|| panic!("`{marker}` not found in {SOURCE}"))
    + marker.len();
  let tags_start = after_oneof
    + message[after_oneof..]
      .find("tags = \"")
      .unwrap_or_else(|| panic!("`{marker}` in {SOURCE} has no tags"))
    + "tags = \"".len();
  let tags_end = tags_start
    + message[tags_start..]
      .find('"')
      .unwrap_or_else(|| panic!("`{marker}` in {SOURCE} has an unterminated tag list"));
  format!("{}{tags}{}", &message[..tags_start], &message[tags_end..])
}

/// Writes `protocol_factory.rs`, included by `protocol_impl/mod.rs`: the exported
/// `protocol_factory!` macro with one arm per protocol, from the protocol list in
/// `get_protocol_identifier` (the one list of protocols), plus a test that every arm's name is
/// the module's `IDENTIFIER`.
///
/// Also emits the protocol names, comma separated, as `links` metadata. A crate that depends on
/// this one directly reads them in its build script as `DEP_BUTTPLUG_SERVER_PROTOCOLS`.
fn protocol_factory() {
  let registry = format!("{PROTOCOLS_DIR}/mod.rs");
  println!("cargo:rerun-if-changed={registry}");
  let source = fs::read_to_string(&registry).expect("protocol registry is readable");
  let function = item(&source, "pub fn get_protocol_identifier(", &registry);

  let mut protocols = Vec::<(String, String)>::new();
  for line in function.lines() {
    let module = line.trim().trim_end_matches(',');
    let is_arm = line.trim().ends_with(',')
      && module != "protocol_identifier"
      && !module.is_empty()
      && module
        .chars()
        .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_' || c == ':');
    if is_arm {
      protocols.push((protocol_identifier(module), module.to_owned()));
    }
  }
  assert!(!protocols.is_empty(), "no protocols found in {registry}");
  protocols.sort();
  for pair in protocols.windows(2) {
    assert!(
      pair[0].0 != pair[1].0,
      "protocol `{}` is listed twice",
      pair[0].0
    );
  }

  let mut out = String::from(
    "// Generated by build.rs from the protocol list in protocol_impl/mod.rs. Do not edit.\n\n\
     /// The [`ProtocolIdentifier`](crate::device::protocol::ProtocolIdentifier) of one protocol, by\n\
     /// its name in the device configuration, e.g. `protocol_factory!(\"lovense\")`.\n\
     ///\n\
     /// Expands to that protocol's `create_identifier()` call and references no other protocol, so\n\
     /// a [`ProtocolLookup`](crate::device::protocol::ProtocolLookup) built from it only links the\n\
     /// protocols it names. An unknown name is a compile error.\n\
     #[macro_export]\n\
     macro_rules! protocol_factory {\n",
  );
  for (identifier, module) in &protocols {
    writeln!(
      out,
      "  ({identifier:?}) => {{ $crate::device::protocol_impl::{module}::setup::create_identifier() }};"
    )
    .unwrap();
  }
  out.push_str(
    "  ($other:literal) => {\n    \
     ::core::compile_error!(::core::concat!(\"buttplug_server has no protocol named \", $other))\n  \
     };\n}\n\n\
     #[cfg(test)]\n\
     #[test]\n\
     fn protocol_factory_names_are_identifiers() {\n",
  );
  for (identifier, module) in &protocols {
    writeln!(
      out,
      "  assert_eq!({module}::setup::IDENTIFIER, {identifier:?});"
    )
    .unwrap();
  }
  out.push_str("}\n");

  let out_dir = env::var("OUT_DIR").expect("cargo sets OUT_DIR");
  fs::write(Path::new(&out_dir).join("protocol_factory.rs"), out)
    .expect("protocol factory macro is writable");

  let names = protocols
    .iter()
    .map(|(identifier, _)| identifier.as_str())
    .collect::<Vec<_>>();
  println!("cargo:protocols={}", names.join(","));
}

/// The protocol identifier a protocol module (as written in the match, e.g. `svakom::svakom_v2`)
/// registers itself under, read from its source.
fn protocol_identifier(module: &str) -> String {
  let path = module.replace("::", "/");
  let file = [
    format!("{PROTOCOLS_DIR}/{path}.rs"),
    format!("{PROTOCOLS_DIR}/{path}/mod.rs"),
  ]
  .into_iter()
  .find(|file| Path::new(file).exists())
  .unwrap_or_else(|| panic!("no source file for protocol module `{module}`"));
  println!("cargo:rerun-if-changed={file}");
  let source = fs::read_to_string(&file).expect("protocol source is readable");

  // The identifier is the string literal in the module's one setup declaration: either one of the
  // setup macros or a hand-written `IDENTIFIER` constant.
  let mut identifiers = [
    "generic_protocol_setup!(",
    "generic_protocol_initializer_setup!(",
    "pub const IDENTIFIER: &str =",
  ]
  .into_iter()
  .flat_map(|declaration| source.match_indices(declaration).map(|(index, _)| index))
  .filter_map(|index| {
    let literal = source[index..].split_once('"')?.1;
    Some(literal.split_once('"')?.0.to_owned())
  });
  let identifier = identifiers
    .next()
    .unwrap_or_else(|| panic!("{file} does not declare a protocol identifier"));
  assert!(
    identifiers.next().is_none(),
    "{file} declares more than one protocol identifier"
  );
  identifier
}
